package dev.homecontrol.app;

import android.media.*;
import android.os.*;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicBoolean;

/** Foreground playback and press-to-talk. Microphone input never goes to storage. */
final class CameraAudio implements AutoCloseable {
    interface Sender{boolean send(byte[] packet);void failed(String message);}
    private final java.util.concurrent.atomic.AtomicLong talkGeneration=new java.util.concurrent.atomic.AtomicLong();private AudioTrack track;private MediaCodec decoder;private int codec,rate,channels;private volatile boolean closed;private final AtomicBoolean talking=new AtomicBoolean();private volatile AudioRecord microphone;
    synchronized void accept(int kind,int sampleRate,int count,byte[] payload)throws Exception{if(closed)return;if(codec!=kind||rate!=sampleRate||channels!=count){releasePlayback();codec=kind;rate=sampleRate;channels=count;int mask=count==2?AudioFormat.CHANNEL_OUT_STEREO:AudioFormat.CHANNEL_OUT_MONO;int size=Math.max(AudioTrack.getMinBufferSize(rate,mask,AudioFormat.ENCODING_PCM_16BIT),rate*count/2);track=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(rate).setChannelMask(mask).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(size).setTransferMode(AudioTrack.MODE_STREAM).build();track.play();if(kind==1032){MediaFormat format=MediaFormat.createAudioFormat("audio/opus",rate,count);byte[] header=new byte[19];System.arraycopy("OpusHead".getBytes(java.nio.charset.StandardCharsets.US_ASCII),0,header,0,8);header[8]=1;header[9]=(byte)count;header[12]=(byte)0x80;header[13]=(byte)0xbb;format.setByteBuffer("csd-0",ByteBuffer.wrap(header));format.setByteBuffer("csd-1",ByteBuffer.wrap(new byte[8]));format.setByteBuffer("csd-2",ByteBuffer.wrap(new byte[8]));decoder=MediaCodec.createDecoderByType("audio/opus");decoder.configure(format,null,null,0);decoder.start();}}
        if(kind==1032){int in=decoder.dequeueInputBuffer(0);if(in>=0){ByteBuffer buffer=decoder.getInputBuffer(in);buffer.clear();buffer.put(payload);decoder.queueInputBuffer(in,0,payload.length,0,0);}MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();for(int n=0;n<8;n++){int out=decoder.dequeueOutputBuffer(info,0);if(out>=0){ByteBuffer buffer=decoder.getOutputBuffer(out);if(buffer!=null&&info.size>0){buffer.position(info.offset);buffer.limit(info.offset+info.size);track.write(buffer,info.size,AudioTrack.WRITE_NON_BLOCKING);}decoder.releaseOutputBuffer(out,false);}else if(out!=MediaCodec.INFO_OUTPUT_FORMAT_CHANGED)break;}}
        else{byte[] pcm=kind==1024?payload:decodeLaw(payload,kind==1027);track.write(pcm,0,pcm.length,AudioTrack.WRITE_NON_BLOCKING);}
    }
    static byte[] decodeLaw(byte[] input,boolean alaw){byte[] pcm=new byte[input.length*2];for(int i=0;i<input.length;i++){int code=input[i]&255,sample;if(alaw){code^=0x55;int exp=(code&0x70)>>4;sample=(code&15)<<4;sample+=exp==0?8:0x108;if(exp>1)sample<<=exp-1;if((code&128)==0)sample=-sample;}else{code=(~code)&255;sample=(((code&15)<<3)+0x84)<<((code&0x70)>>4);sample-=0x84;if((code&128)!=0)sample=-sample;}pcm[2*i]=(byte)sample;pcm[2*i+1]=(byte)(sample>>8);}return pcm;}
    private static final byte[][] LAW_TABLES={lawTable(false),lawTable(true)};
    private static byte[] lawTable(boolean alaw){byte[] values=new byte[256];for(int i=0;i<256;i++)values[i]=(byte)i;return decodeLaw(values,alaw);}
    static byte[] encodeLaw(byte[] pcm,int length,boolean alaw){byte[] out=new byte[length/2],table=LAW_TABLES[alaw?1:0];for(int i=0;i<out.length;i++){int sample=(short)((pcm[i*2]&255)|pcm[i*2+1]<<8),best=0,distance=Integer.MAX_VALUE;for(int code=0;code<256;code++){int candidate=(short)((table[code*2]&255)|table[code*2+1]<<8),delta=Math.abs(sample-candidate);if(delta<distance){distance=delta;best=code;}}out[i]=(byte)best;}return out;}
    void startTalk(Sender sender,int audioCodec,int audioRate){if(closed||!talking.compareAndSet(false,true))return;final long token=talkGeneration.incrementAndGet();new Thread(()->{MediaCodec encoder=null;AudioRecord input=null;try{int sampleRate=audioCodec==1032?48000:audioRate;if(sampleRate!=8000&&sampleRate!=16000&&sampleRate!=48000)throw new IllegalArgumentException();int bufferSize=Math.max(7680,AudioRecord.getMinBufferSize(sampleRate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT));input=new AudioRecord.Builder().setAudioSource(MediaRecorder.AudioSource.VOICE_COMMUNICATION).setAudioFormat(new AudioFormat.Builder().setSampleRate(sampleRate).setChannelMask(AudioFormat.CHANNEL_IN_MONO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(bufferSize).build();microphone=input;if(input.getState()!=AudioRecord.STATE_INITIALIZED)throw new IllegalStateException();if(audioCodec==1032){MediaFormat format=MediaFormat.createAudioFormat("audio/opus",sampleRate,1);format.setInteger(MediaFormat.KEY_BIT_RATE,24000);encoder=MediaCodec.createEncoderByType("audio/opus");encoder.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encoder.start();}input.startRecording();byte[] raw=new byte[sampleRate/50*2];long samples=0;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(talking.get()&&!closed&&talkGeneration.get()==token){int length=input.read(raw,0,raw.length,AudioRecord.READ_BLOCKING);if(length<=0)continue;if(audioCodec!=1032){byte[] packet=audioCodec==1024?java.util.Arrays.copyOf(raw,length):encodeLaw(raw,length,audioCodec==1027);if(!sender.send(packet))throw new IllegalStateException();continue;}int index=encoder.dequeueInputBuffer(10000);if(index>=0){ByteBuffer data=encoder.getInputBuffer(index);data.clear();data.put(raw,0,length);encoder.queueInputBuffer(index,0,length,samples*1000000/sampleRate,0);samples+=length/2;}for(int n=0;n<4;n++){int out=encoder.dequeueOutputBuffer(info,0);if(out<0)break;ByteBuffer data=encoder.getOutputBuffer(out);if(data!=null&&info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){byte[] packet=new byte[info.size];data.position(info.offset);data.get(packet);if(!sender.send(packet))throw new IllegalStateException();}encoder.releaseOutputBuffer(out,false);}}}catch(Exception e){if(talking.get()&&!closed&&talkGeneration.get()==token)sender.failed("当前手机或摄像机的对讲连接未完成");}finally{if(talkGeneration.get()==token)talking.set(false);if(microphone==input)microphone=null;if(input!=null){try{input.stop();}catch(Exception ignored){}input.release();}if(encoder!=null){try{encoder.stop();}catch(Exception ignored){}encoder.release();}}},"JiaJuTalkMicrophone").start();}
    void stopTalk(){talkGeneration.incrementAndGet();talking.set(false);AudioRecord input=microphone;if(input!=null)try{input.stop();}catch(Exception ignored){}}
    private void releasePlayback(){if(decoder!=null){try{decoder.stop();}catch(Exception ignored){}decoder.release();decoder=null;}if(track!=null){try{track.stop();}catch(Exception ignored){}track.release();track=null;}}
    @Override public synchronized void close(){closed=true;stopTalk();releasePlayback();}
}
